:root {
  font-family: "Manrope Variable", sans-serif;
  color: #f0edf3;
  background: #000;
  color-scheme: dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --surface: #111;
  --text: #f0edf3;
  --muted: #ada6b4;
  --accent: #b67be5;
  --line: #28232e;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-width: 320px;
}
button,
input {
  font: inherit;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
}
a {
  color: inherit;
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 5px;
}
::selection {
  color: #fff;
  background: #5c277f;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.skip-link {
  position: absolute;
  left: 24px;
  top: 16px;
  transform: translateY(-180%);
  padding: 12px 16px;
  background: var(--surface);
  z-index: 2;
}
.skip-link:focus {
  transform: none;
}
.app-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: 0 auto;
  padding: 0 64px;
  display: flex;
  flex-direction: column;
}
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 32px 0;
  border-bottom: 1px solid #1c1920;
}
.wordmark {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  font-size: 29px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -1.7px;
  text-decoration: none;
}
.header-context {
  color: var(--muted);
  font-size: 13px;
}
main {
  width: min(100%, 800px);
  margin: 74px auto 48px;
  flex: 1;
}
.search-intro {
  margin-bottom: 30px;
}
h1 {
  font-size: clamp(28px, 3.1vw, 38px);
  line-height: 1.2;
  letter-spacing: -1.4px;
  font-weight: 600;
  margin: 0 0 13px;
}
.search-intro p {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.7;
  margin: 0;
}
.search-field {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 22px;
  min-height: 74px;
  border: 1px solid #493553;
  border-radius: 10px;
  background: var(--surface);
  transition:
    border-color 120ms ease,
    box-shadow 120ms ease;
}
.search-field:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px #a863d61c;
}
.search-icon {
  display: flex;
  color: var(--accent);
  flex: none;
}
.search-field input {
  appearance: none;
  background: transparent;
  color: var(--text);
  border: 0;
  outline: none;
  min-width: 0;
  width: 100%;
  padding: 21px 0;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.6;
  caret-color: var(--accent);
}
.search-field input::-webkit-search-cancel-button {
  display: none;
}
.search-field input::placeholder {
  color: #9c929f;
  font-weight: 400;
}
.search-shortcut {
  flex: none;
  white-space: nowrap;
  font: inherit;
  font-size: 14px;
  color: var(--muted);
  border: 1px solid #453c4a;
  border-radius: 5px;
  min-width: 26px;
  padding: 2px 7px;
